function t(t){if(null==t||""==t.trim())return console.error("openWeb: URL参数不能为空"),!1;try{let e=t.trim();return!e.includes(".")||e.length<4?(console.error("openWeb: 无效的URL格式 -",e),!1):(e.startsWith("http://")||e.startsWith("https://")||e.startsWith("//")||(e="https://"+e),location.href=e,console.log("openWeb: 成功打开URL -",e),!0)}catch(e){return console.error("openWeb: 打开URL时发生错误 -",e),!1}}export{t as o};
